import java.util.*;
import java.io.*;

public class Main {
    static final long MOD_A = 998244353L;
    static final long MOD_B = 1000000007L;
    static long answer_value;
    static long total_numbers;
    static long counter1;
    static List<Long>[] digit_buckets = new ArrayList[7];
    static long[] prefix_sums = new long[7];
    static long[] power_array = {1, 10, 100, 1000, 10000, 100000, 1000000};
    static long count_pairs;

    static {
        for (int i = 0; i < 7; i++) {
            digit_buckets[i] = new ArrayList<>();
        }
    }

    static void generate_bucket(int level, long current) {
        if (level == 7) return;
        long val = (total_numbers - current + MOD_A) % MOD_A;
        digit_buckets[level].add(val);
        prefix_sums[level] += val;
        total_numbers++;
        for (int digit = 0; digit <= 9; digit++) {
            generate_bucket(level + 1, current * 10 + digit);
        }
    }

    static boolean is_in_range(long x) {
        return x * 1000000 + 999999 <= total_numbers && x * 10000000 > total_numbers;
    }

    static void explore(long level, long val) {
        if (val > total_numbers) return;
        if (is_in_range(val)) {
            for (int i = 0; i <= 6; i++) {
                long offset = ((counter1 + 1 - (val * power_array[i]) % MOD_A) + MOD_A) % MOD_A;
                List<Long> bucket = digit_buckets[i];
                int pos = lowerBound(bucket, MOD_A - offset);
                long size = bucket.size();
                long sum_prefix = prefix_sums[i];
                long sum_before_pos = (pos > 0) ? sumRange(prefix_sums, 0, pos - 1) : 0;
                long sum_after_pos = sumRange(prefix_sums, pos, (int) size - 1);
                long contribution = (sum_prefix + offset * size - MOD_A * (size - pos)) % MOD_B;
                answer_value = (answer_value + contribution) % MOD_B;
            }
            count_pairs += 1;
        } else {
            count_pairs++;
            answer_value = (answer_value + ((count_pairs - val) % MOD_A + MOD_A) % MOD_A) % MOD_B;
            for (int d = (level == 0) ? 1 : 0; d <= 9; d++) {
                explore(level + 1, val * 10 + d);
            }
        }
    }

    static int lowerBound(List<Long> list, long target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= target) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    static long sumRange(long[] prefix, int start, int end) {
        if (start > end) return 0;
        return prefix[end] - (start > 0 ? prefix[start - 1] : 0);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        total_numbers = Long.parseLong(br.readLine().trim());
        generate_bucket(0, 0);
        for (int i = 0; i <= 6; i++) {
            Collections.sort(digit_buckets[i]);
            prefix_sums[i] = 0;
            for (int j = 0; j < digit_buckets[i].size(); j++) {
                prefix_sums[i] += digit_buckets[i].get(j);
            }
        }
        count_pairs = -1;
        answer_value = 0;
        explore(0, 0);
        System.out.println(answer_value);
    }
}
